INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15924, 'Sunshine Pictures IPO Opens with Price Band ₹342-₹360', 'सनशाइन पिक्चर्स का आईपीओ ₹342-₹360 के प्राइस बैंड के साथ खुला', 'Sunshine Pictures launched its Initial Public Offering (IPO) with a price band set between ₹342 and ₹360 per share. The IPO opened for subscription, and analysts are providing guidance on whether investors should apply or avoid it. Market sentiment, indicated by Grey Market Premium (GMP), is also being considered.', 'सनशाइन पिक्चर्स ने ₹342 से ₹360 प्रति शेयर के प्राइस बैंड के साथ अपना इनिशियल पब्लिक ऑफरिंग (आईपीओ) लॉन्च किया। आईपीओ सब्सक्रिप्शन के लिए खुल गया है, और विश्लेषक निवेशकों को आवेदन करना चाहिए या नहीं, इस पर मार्गदर्शन दे रहे हैं। ग्रे मार्केट प्रीमियम (जीएमपी) से बाजार की भावना का भी आकलन किया जा रहा है।', '["Sunshine Pictures IPO opened for subscription.", "The price band for the IPO is fixed at ₹342 to ₹360 per share.", "Analysts are offering advice to potential investors regarding application.", "Grey Market Premium (GMP) is being monitored for market sentiment."]'::jsonb, '["सनशाइन पिक्चर्स का आईपीओ सब्सक्रिप्शन के लिए खुल गया है।", "आईपीओ के लिए प्राइस बैंड ₹342 से ₹360 प्रति शेयर तय किया गया है।", "विश्लेषक संभावित निवेशकों को आवेदन के संबंध में सलाह दे रहे हैं।", "बाजार की भावना के लिए ग्रे मार्केट प्रीमियम (जीएमपी) की निगरानी की जा रही है।"]'::jsonb, 'Economy', 'India', 0, 2, 0, 0, 0, 2, 'center', 100, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["Business Today", "The Free Press Journal"], "owners": ["India Today Group", "The Free Press Journal"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"center": ["Reported the opening of Sunshine Pictures IPO.", "Stated the IPO''s price band of ₹342-₹360.", "Mentioned that analysts are providing application advice.", "Noted the consideration of Grey Market Premium (GMP) for market sentiment."]}'::jsonb, '{"center": ["सनशाइन पिक्चर्स के आईपीओ के खुलने की सूचना दी।", "आईपीओ के ₹342-₹360 के प्राइस बैंड का उल्लेख किया।", "बताया कि विश्लेषक आवेदन संबंधी सलाह दे रहे हैं।", "बाजार की भावना के लिए ग्रे मार्केट प्रीमियम (जीएमपी) पर विचार करने का उल्लेख किया।"]}'::jsonb, '[{"source": "Business Today", "owner": "India Today Group", "lean": "center", "language": "en", "url": "https://www.businesstoday.in/markets/ipo-corner/story/sunshine-pictures-ipo-kicksoff-should-you-apply-or-avoid-heres-what-analyst-say-check-gmp-549723-2026-08-18", "headline": "Sunshine Pictures IPO kicksoff : Should you apply or avoid ? Here what analyst say , check GMP"}, {"source": "The Free Press Journal", "owner": "The Free Press Journal", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Sunshine Pictures IPO Opens, Price Band Fixed At ₹342-₹360"}]'::jsonb, '{"title": "Sunshine Pictures IPO Opens with Price Band ₹342-₹360", "summary": "Sunshine Pictures launched its Initial Public Offering (IPO) with a price band set between ₹342 and ₹360 per share. The IPO opened for subscription, and analysts are providing guidance on whether investors should apply or avoid it. Market sentiment, indicated by Grey Market Premium (GMP), is also being considered.", "summary_points": ["Sunshine Pictures IPO opened for subscription.", "The price band for the IPO is fixed at ₹342 to ₹360 per share.", "Analysts are offering advice to potential investors regarding application.", "Grey Market Premium (GMP) is being monitored for market sentiment."], "title_hi": "सनशाइन पिक्चर्स का आईपीओ ₹342-₹360 के प्राइस बैंड के साथ खुला", "summary_hi": "सनशाइन पिक्चर्स ने ₹342 से ₹360 प्रति शेयर के प्राइस बैंड के साथ अपना इनिशियल पब्लिक ऑफरिंग (आईपीओ) लॉन्च किया। आईपीओ सब्सक्रिप्शन के लिए खुल गया है, और विश्लेषक निवेशकों को आवेदन करना चाहिए या नहीं, इस पर मार्गदर्शन दे रहे हैं। ग्रे मार्केट प्रीमियम (जीएमपी) से बाजार की भावना का भी आकलन किया जा रहा है।", "summary_points_hi": ["सनशाइन पिक्चर्स का आईपीओ सब्सक्रिप्शन के लिए खुल गया है।", "आईपीओ के लिए प्राइस बैंड ₹342 से ₹360 प्रति शेयर तय किया गया है।", "विश्लेषक संभावित निवेशकों को आवेदन के संबंध में सलाह दे रहे हैं।", "बाजार की भावना के लिए ग्रे मार्केट प्रीमियम (जीएमपी) की निगरानी की जा रही है।"], "framing": {"center": ["Reported the opening of Sunshine Pictures IPO.", "Stated the IPO''s price band of ₹342-₹360.", "Mentioned that analysts are providing application advice.", "Noted the consideration of Grey Market Premium (GMP) for market sentiment."]}, "framing_hi": {"center": ["सनशाइन पिक्चर्स के आईपीओ के खुलने की सूचना दी।", "आईपीओ के ₹342-₹360 के प्राइस बैंड का उल्लेख किया।", "बताया कि विश्लेषक आवेदन संबंधी सलाह दे रहे हैं।", "बाजार की भावना के लिए ग्रे मार्केट प्रीमियम (जीएमपी) पर विचार करने का उल्लेख किया।"]}, "topic": "Economy", "region": "India", "published_at": null, "image_url": "https://akm-img-a-in.tosshub.com/businesstoday/images/story/202608/6a83ebc26dd4d-ai-generated-image-for-representational-purpose-only-182100913-16x9.png", "sources": [{"source": "Business Today", "owner": "India Today Group", "lean": "center", "language": "en", "url": "https://www.businesstoday.in/markets/ipo-corner/story/sunshine-pictures-ipo-kicksoff-should-you-apply-or-avoid-heres-what-analyst-say-check-gmp-549723-2026-08-18", "headline": "Sunshine Pictures IPO kicksoff : Should you apply or avoid ? Here what analyst say , check GMP"}, {"source": "The Free Press Journal", "owner": "The Free Press Journal", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Sunshine Pictures IPO Opens, Price Band Fixed At ₹342-₹360"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["Business Today", "The Free Press Journal"], "owners": ["India Today Group", "The Free Press Journal"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://akm-img-a-in.tosshub.com/businesstoday/images/story/202608/6a83ebc26dd4d-ai-generated-image-for-representational-purpose-only-182100913-16x9.png', FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.330371'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15923, 'Maruti Suzuki Increases Prices Across All Car Models', 'मारुति सुजुकी ने सभी कार मॉडलों की कीमतें बढ़ाईं', 'Maruti Suzuki has raised the prices of all its car models, including the Dzire, new Brezza, Ertiga, and Fronx. The price hike affects vehicles ranging from the Alto K10 to the Vitara. Specific details on the extent of the price increase for each model were not provided in the coverage.', 'मारुति सुजुकी ने अपनी सभी कार मॉडलों की कीमतें बढ़ा दी हैं, जिनमें डिजायर, नई ब्रेजा, अर्टिगा और फ्रॉन्क्स शामिल हैं। कीमत वृद्धि ऑल्टो K10 से लेकर विटारा तक के वाहनों को प्रभावित करती है। कवरेज में प्रत्येक मॉडल के लिए मूल्य वृद्धि की सीमा पर विशिष्ट विवरण प्रदान नहीं किया गया था।', '["Maruti Suzuki has increased the prices of all its car models.", "Models affected include Dzire, new Brezza, Ertiga, and Fronx.", "The price increase extends to vehicles from the Alto K10 to the Vitara.", "Specific figures for the price hikes on individual models were not detailed."]'::jsonb, '["मारुति सुजुकी ने अपने सभी कार मॉडलों की कीमतें बढ़ाई हैं।", "प्रभावित मॉडलों में डिजायर, नई ब्रेजा, अर्टिगा और फ्रॉन्क्स शामिल हैं।", "कीमत वृद्धि ऑल्टो K10 से विटारा तक के वाहनों तक फैली हुई है।", "अलग-अलग मॉडलों पर मूल्य वृद्धि के विशिष्ट आंकड़े विस्तृत नहीं किए गए थे।"]'::jsonb, 'Economy', 'India', 0, 2, 0, 0, 0, 2, 'center', 100, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["Haribhoomi", "Navbharat Times"], "owners": ["Haribhoomi", "Times Group"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"center": ["Reported that Maruti Suzuki has increased prices across its entire car range.", "Mentioned specific models affected, including Dzire, Brezza, Ertiga, and Fronx.", "Noted that the price hike covers vehicles from Alto K10 to Vitara.", "Highlighted that specific price increase amounts for each model were not detailed."]}'::jsonb, '{"center": ["रिपोर्ट किया कि मारुति सुजुकी ने अपनी पूरी कार श्रृंखला में कीमतें बढ़ाई हैं।", "डिजायर, ब्रेजा, अर्टिगा और फ्रॉन्क्स सहित प्रभावित विशिष्ट मॉडलों का उल्लेख किया।", "ध्यान दिया कि मूल्य वृद्धि ऑल्टो K10 से विटारा तक के वाहनों को कवर करती है।", "इस बात पर प्रकाश डाला कि प्रत्येक मॉडल के लिए मूल्य वृद्धि की विशिष्ट राशि का विवरण नहीं दिया गया था।"]}'::jsonb, '[{"source": "Navbharat Times", "owner": "Times Group", "lean": "center", "language": "hi", "url": "https://navbharattimes.indiatimes.com/auto/car-bikes/maruti-suzuki-announces-price-hike-across-model-lineup-in-august-2026-see-model-wise-new-prices-dzire-brezza-fronx/articleshow/133311080.cms", "headline": "मारुति सुजुकी ने सभी कारों के बढ़ाए दाम , डिजायर और नई ब्रेजा के साथ ही अर्टिगा - फ्रॉन्क्स समेत सभी मॉडल्स की बढ़ीं कीमतें जानें"}, {"source": "Haribhoomi", "owner": "Haribhoomi", "lean": "center", "language": "hi", "url": "https://news.google.com/rss/articles/CBMisgFBVV95cUxQWWZfenFnR2dXRGQ0VTkyYmplZzl3OUdOa0xhQ1Z4VE95RXRqMWtEUm5lZVF0RXhLSlU2ZURjMGpXVEo3TEI4ZkkxM1JjYmgtY0RVaDVZbmJPOVYzVG9vaUt5SlZYYWFlVUdMblM0S2gzeG9DSF83UTV4c0RLZHpOSXgzWkJaQjZVNjU5TUhMNEEySnNkVGs2VFAwTlNZdW9MQXpGT0c1QXFGLW1qQlpDcTdB?oc=5", "headline": "Price Hike: ऑल्टो K10 से विक्टोरिस तक महंगी हुईं ये कारें, जानें किसकी कितनी बढ़ी कीमतें?"}]'::jsonb, '{"title": "Maruti Suzuki Increases Prices Across All Car Models", "summary": "Maruti Suzuki has raised the prices of all its car models, including the Dzire, new Brezza, Ertiga, and Fronx. The price hike affects vehicles ranging from the Alto K10 to the Vitara. Specific details on the extent of the price increase for each model were not provided in the coverage.", "summary_points": ["Maruti Suzuki has increased the prices of all its car models.", "Models affected include Dzire, new Brezza, Ertiga, and Fronx.", "The price increase extends to vehicles from the Alto K10 to the Vitara.", "Specific figures for the price hikes on individual models were not detailed."], "title_hi": "मारुति सुजुकी ने सभी कार मॉडलों की कीमतें बढ़ाईं", "summary_hi": "मारुति सुजुकी ने अपनी सभी कार मॉडलों की कीमतें बढ़ा दी हैं, जिनमें डिजायर, नई ब्रेजा, अर्टिगा और फ्रॉन्क्स शामिल हैं। कीमत वृद्धि ऑल्टो K10 से लेकर विटारा तक के वाहनों को प्रभावित करती है। कवरेज में प्रत्येक मॉडल के लिए मूल्य वृद्धि की सीमा पर विशिष्ट विवरण प्रदान नहीं किया गया था।", "summary_points_hi": ["मारुति सुजुकी ने अपने सभी कार मॉडलों की कीमतें बढ़ाई हैं।", "प्रभावित मॉडलों में डिजायर, नई ब्रेजा, अर्टिगा और फ्रॉन्क्स शामिल हैं।", "कीमत वृद्धि ऑल्टो K10 से विटारा तक के वाहनों तक फैली हुई है।", "अलग-अलग मॉडलों पर मूल्य वृद्धि के विशिष्ट आंकड़े विस्तृत नहीं किए गए थे।"], "framing": {"center": ["Reported that Maruti Suzuki has increased prices across its entire car range.", "Mentioned specific models affected, including Dzire, Brezza, Ertiga, and Fronx.", "Noted that the price hike covers vehicles from Alto K10 to Vitara.", "Highlighted that specific price increase amounts for each model were not detailed."]}, "framing_hi": {"center": ["रिपोर्ट किया कि मारुति सुजुकी ने अपनी पूरी कार श्रृंखला में कीमतें बढ़ाई हैं।", "डिजायर, ब्रेजा, अर्टिगा और फ्रॉन्क्स सहित प्रभावित विशिष्ट मॉडलों का उल्लेख किया।", "ध्यान दिया कि मूल्य वृद्धि ऑल्टो K10 से विटारा तक के वाहनों को कवर करती है।", "इस बात पर प्रकाश डाला कि प्रत्येक मॉडल के लिए मूल्य वृद्धि की विशिष्ट राशि का विवरण नहीं दिया गया था।"]}, "topic": "Economy", "region": "India", "published_at": null, "image_url": "https://static.langimg.com/nbt/thumb/133311178/maruti-suzuki-cars-price-latest-hike-in-august-2026.jpg?imgsize=2227027&resizemode=75", "sources": [{"source": "Navbharat Times", "owner": "Times Group", "lean": "center", "language": "hi", "url": "https://navbharattimes.indiatimes.com/auto/car-bikes/maruti-suzuki-announces-price-hike-across-model-lineup-in-august-2026-see-model-wise-new-prices-dzire-brezza-fronx/articleshow/133311080.cms", "headline": "मारुति सुजुकी ने सभी कारों के बढ़ाए दाम , डिजायर और नई ब्रेजा के साथ ही अर्टिगा - फ्रॉन्क्स समेत सभी मॉडल्स की बढ़ीं कीमतें जानें"}, {"source": "Haribhoomi", "owner": "Haribhoomi", "lean": "center", "language": "hi", "url": "https://news.google.com/rss/articles/CBMisgFBVV95cUxQWWZfenFnR2dXRGQ0VTkyYmplZzl3OUdOa0xhQ1Z4VE95RXRqMWtEUm5lZVF0RXhLSlU2ZURjMGpXVEo3TEI4ZkkxM1JjYmgtY0RVaDVZbmJPOVYzVG9vaUt5SlZYYWFlVUdMblM0S2gzeG9DSF83UTV4c0RLZHpOSXgzWkJaQjZVNjU5TUhMNEEySnNkVGs2VFAwTlNZdW9MQXpGT0c1QXFGLW1qQlpDcTdB?oc=5", "headline": "Price Hike: ऑल्टो K10 से विक्टोरिस तक महंगी हुईं ये कारें, जानें किसकी कितनी बढ़ी कीमतें?"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["Haribhoomi", "Navbharat Times"], "owners": ["Haribhoomi", "Times Group"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://static.langimg.com/nbt/thumb/133311178/maruti-suzuki-cars-price-latest-hike-in-august-2026.jpg?imgsize=2227027&resizemode=75', FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.307742'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15922, 'NITI Aayog Sets $81 Billion Chemical Export Target for 2030 Amid Challenges', 'नीति आयोग ने 2030 तक रासायनिक निर्यात के लिए $81 बिलियन का लक्ष्य निर्धारित किया, चुनौतियों के बीच', 'NITI Aayog has set a target of $81 billion for India''s chemical sector exports by 2030. While outlining this goal, the Aayog also acknowledged that challenges exist in achieving it. The Economic Times reported that the chemicals industry sees an export runway to reach this $81 billion mark by the target year. The Financial Express noted the specific target and the presence of challenges.', 'नीति आयोग ने 2030 तक भारत के रासायनिक क्षेत्र के निर्यात के लिए $81 बिलियन का लक्ष्य निर्धारित किया है। इस लक्ष्य की रूपरेखा तैयार करते हुए, आयोग ने यह भी स्वीकार किया कि इसे प्राप्त करने में चुनौतियां मौजूद हैं। इकोनॉमिक टाइम्स ने बताया कि रसायन उद्योग 2030 तक इस $81 बिलियन के आंकड़े तक पहुंचने के लिए एक निर्यात रनवे देखता है। फाइनेंशियल एक्सप्रेस ने विशिष्ट लक्ष्य और चुनौतियों की उपस्थिति पर ध्यान दिया।', '["NITI Aayog has set a target of $81 billion for India''s chemical sector exports by 2030.", "The Aayog acknowledged that challenges exist in achieving this export target.", "The chemicals industry is seen as having a potential export runway to reach $81 billion by 2030.", "The target was reported by both The Financial Express and The Economic Times."]'::jsonb, '["नीति आयोग ने 2030 तक भारत के रासायनिक क्षेत्र के निर्यात के लिए $81 बिलियन का लक्ष्य निर्धारित किया है।", "आयोग ने स्वीकार किया कि इस निर्यात लक्ष्य को प्राप्त करने में चुनौतियां मौजूद हैं।", "रसायन उद्योग को 2030 तक $81 बिलियन तक पहुंचने के लिए एक संभावित निर्यात रनवे के रूप में देखा जाता है।", "यह लक्ष्य फाइनेंशियल एक्सप्रेस और इकोनॉमिक टाइम्स दोनों द्वारा रिपोर्ट किया गया था।"]'::jsonb, 'Economy', 'India', 0, 2, 0, 0, 0, 2, 'center', 100, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["The Economic Times", "The Financial Express"], "owners": ["Indian Express Group", "Times Group"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"center": ["Outlets reported NITI Aayog''s $81 billion export target for the chemical sector by 2030.", "Coverage noted the existence of challenges in achieving this target.", "The potential for the industry to reach the target was highlighted."]}'::jsonb, '{"center": ["आउटलेट्स ने 2030 तक रासायनिक क्षेत्र के लिए नीति आयोग के $81 बिलियन के निर्यात लक्ष्य की सूचना दी।", "कवरेज में इस लक्ष्य को प्राप्त करने में चुनौतियों के अस्तित्व का उल्लेख किया गया।", "उद्योग द्वारा लक्ष्य तक पहुंचने की क्षमता पर प्रकाश डाला गया।"]}'::jsonb, '[{"source": "The Financial Express", "owner": "Indian Express Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "NITI Aayog outlines $81 billion export target for chemical sector by 2030, but there are challenges"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "India’s chemicals industry sees export runway to $81 billion by 2030"}]'::jsonb, '{"title": "NITI Aayog Sets $81 Billion Chemical Export Target for 2030 Amid Challenges", "summary": "NITI Aayog has set a target of $81 billion for India''s chemical sector exports by 2030. While outlining this goal, the Aayog also acknowledged that challenges exist in achieving it. The Economic Times reported that the chemicals industry sees an export runway to reach this $81 billion mark by the target year. The Financial Express noted the specific target and the presence of challenges.", "summary_points": ["NITI Aayog has set a target of $81 billion for India''s chemical sector exports by 2030.", "The Aayog acknowledged that challenges exist in achieving this export target.", "The chemicals industry is seen as having a potential export runway to reach $81 billion by 2030.", "The target was reported by both The Financial Express and The Economic Times."], "title_hi": "नीति आयोग ने 2030 तक रासायनिक निर्यात के लिए $81 बिलियन का लक्ष्य निर्धारित किया, चुनौतियों के बीच", "summary_hi": "नीति आयोग ने 2030 तक भारत के रासायनिक क्षेत्र के निर्यात के लिए $81 बिलियन का लक्ष्य निर्धारित किया है। इस लक्ष्य की रूपरेखा तैयार करते हुए, आयोग ने यह भी स्वीकार किया कि इसे प्राप्त करने में चुनौतियां मौजूद हैं। इकोनॉमिक टाइम्स ने बताया कि रसायन उद्योग 2030 तक इस $81 बिलियन के आंकड़े तक पहुंचने के लिए एक निर्यात रनवे देखता है। फाइनेंशियल एक्सप्रेस ने विशिष्ट लक्ष्य और चुनौतियों की उपस्थिति पर ध्यान दिया।", "summary_points_hi": ["नीति आयोग ने 2030 तक भारत के रासायनिक क्षेत्र के निर्यात के लिए $81 बिलियन का लक्ष्य निर्धारित किया है।", "आयोग ने स्वीकार किया कि इस निर्यात लक्ष्य को प्राप्त करने में चुनौतियां मौजूद हैं।", "रसायन उद्योग को 2030 तक $81 बिलियन तक पहुंचने के लिए एक संभावित निर्यात रनवे के रूप में देखा जाता है।", "यह लक्ष्य फाइनेंशियल एक्सप्रेस और इकोनॉमिक टाइम्स दोनों द्वारा रिपोर्ट किया गया था।"], "framing": {"center": ["Outlets reported NITI Aayog''s $81 billion export target for the chemical sector by 2030.", "Coverage noted the existence of challenges in achieving this target.", "The potential for the industry to reach the target was highlighted."]}, "framing_hi": {"center": ["आउटलेट्स ने 2030 तक रासायनिक क्षेत्र के लिए नीति आयोग के $81 बिलियन के निर्यात लक्ष्य की सूचना दी।", "कवरेज में इस लक्ष्य को प्राप्त करने में चुनौतियों के अस्तित्व का उल्लेख किया गया।", "उद्योग द्वारा लक्ष्य तक पहुंचने की क्षमता पर प्रकाश डाला गया।"]}, "topic": "Economy", "region": "India", "published_at": null, "image_url": "", "sources": [{"source": "The Financial Express", "owner": "Indian Express Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "NITI Aayog outlines $81 billion export target for chemical sector by 2030, but there are challenges"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "India’s chemicals industry sees export runway to $81 billion by 2030"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["The Economic Times", "The Financial Express"], "owners": ["Indian Express Group", "Times Group"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, NULL, FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.283849'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15921, 'Indian AI Firm Fractal Secures Over $17 Million Deal with US Healthcare Company', 'भारतीय एआई फर्म फ्रैक्टल ने अमेरिकी स्वास्थ्य सेवा कंपनी के साथ 17 मिलियन डॉलर से अधिक का सौदा किया', 'Indian AI and data analytics company Fractal has secured a multi-year deal worth over US$17 million with a Fortune 500 U.S. healthcare organization. The agreement involves providing AI and analytics services. The deal highlights Fractal''s growing international presence and its capacity to secure significant contracts with major global corporations.', 'भारतीय एआई और डेटा एनालिटिक्स कंपनी फ्रैक्टल ने एक फॉर्च्यून 500 अमेरिकी स्वास्थ्य सेवा संगठन के साथ 17 मिलियन डॉलर से अधिक का बहु-वर्षीय सौदा हासिल किया है। इस समझौते में एआई और एनालिटिक्स सेवाएं प्रदान करना शामिल है। यह सौदा फ्रैक्टल की बढ़ती अंतरराष्ट्रीय उपस्थिति और प्रमुख वैश्विक निगमों के साथ महत्वपूर्ण अनुबंध हासिल करने की उसकी क्षमता को उजागर करता है।', '["Fractal, an Indian AI and data analytics firm, has signed a deal worth over US$17 million.", "The contract is multi-year and with a Fortune 500 healthcare organization in the U.S.", "The deal is for the provision of AI and analytics services.", "This contract signifies a significant international business win for Fractal."]'::jsonb, '["भारतीय एआई और डेटा एनालिटिक्स फर्म फ्रैक्टल ने 17 मिलियन डॉलर से अधिक का सौदा किया है।", "यह अनुबंध बहु-वर्षीय है और अमेरिका में एक फॉर्च्यून 500 स्वास्थ्य सेवा संगठन के साथ है।", "यह सौदा एआई और एनालिटिक्स सेवाओं के प्रावधान के लिए है।", "यह अनुबंध फ्रैक्टल के लिए एक महत्वपूर्ण अंतरराष्ट्रीय व्यावसायिक जीत का प्रतीक है।"]'::jsonb, 'Economy', 'World', 1, 1, 0, 0, 0, 2, 'left', 50, NULL, NULL, '{"left": {"count": 1, "sources": ["The Hindu"], "owners": ["The Hindu Group"]}, "center": {"count": 1, "sources": ["The Hindu BusinessLine"], "owners": ["The Hindu Group"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "The Hindu", "owner": "The Hindu Group", "lean": "left", "language": "en", "url": "https://www.thehindu.com/brandhub/pr-release/fractal-wins-us-17m-multi-year-ai-deal-with-a-fortune-500-u-s-healthcare-organization/article71359919.ece", "headline": "Fractal Wins US$17M+ Multi-Year AI Deal with a Fortune 500® U.S. Healthcare Organization"}, {"source": "The Hindu BusinessLine", "owner": "The Hindu Group", "lean": "center", "language": "en", "url": "https://www.thehindubusinessline.com/brandhub/pr-release/fractal-wins-us-17m-multi-year-ai-deal-with-a-fortune-500-u-s-healthcare-organization/article71359921.ece", "headline": "Fractal Wins US$17M+ Multi-Year AI Deal with a Fortune 500® U.S. Healthcare Organization"}]'::jsonb, '{"title": "Indian AI Firm Fractal Secures Over $17 Million Deal with US Healthcare Company", "summary": "Indian AI and data analytics company Fractal has secured a multi-year deal worth over US$17 million with a Fortune 500 U.S. healthcare organization. The agreement involves providing AI and analytics services. The deal highlights Fractal''s growing international presence and its capacity to secure significant contracts with major global corporations.", "summary_points": ["Fractal, an Indian AI and data analytics firm, has signed a deal worth over US$17 million.", "The contract is multi-year and with a Fortune 500 healthcare organization in the U.S.", "The deal is for the provision of AI and analytics services.", "This contract signifies a significant international business win for Fractal."], "title_hi": "भारतीय एआई फर्म फ्रैक्टल ने अमेरिकी स्वास्थ्य सेवा कंपनी के साथ 17 मिलियन डॉलर से अधिक का सौदा किया", "summary_hi": "भारतीय एआई और डेटा एनालिटिक्स कंपनी फ्रैक्टल ने एक फॉर्च्यून 500 अमेरिकी स्वास्थ्य सेवा संगठन के साथ 17 मिलियन डॉलर से अधिक का बहु-वर्षीय सौदा हासिल किया है। इस समझौते में एआई और एनालिटिक्स सेवाएं प्रदान करना शामिल है। यह सौदा फ्रैक्टल की बढ़ती अंतरराष्ट्रीय उपस्थिति और प्रमुख वैश्विक निगमों के साथ महत्वपूर्ण अनुबंध हासिल करने की उसकी क्षमता को उजागर करता है।", "summary_points_hi": ["भारतीय एआई और डेटा एनालिटिक्स फर्म फ्रैक्टल ने 17 मिलियन डॉलर से अधिक का सौदा किया है।", "यह अनुबंध बहु-वर्षीय है और अमेरिका में एक फॉर्च्यून 500 स्वास्थ्य सेवा संगठन के साथ है।", "यह सौदा एआई और एनालिटिक्स सेवाओं के प्रावधान के लिए है।", "यह अनुबंध फ्रैक्टल के लिए एक महत्वपूर्ण अंतरराष्ट्रीय व्यावसायिक जीत का प्रतीक है।"], "framing": {}, "framing_hi": {}, "topic": "Economy", "region": "World", "published_at": null, "image_url": "https://th-i.thgim.com/public/incoming/5vknad/article71359918.ece/alternates/LANDSCAPE_1200/Fractal_Logo.jpg", "sources": [{"source": "The Hindu", "owner": "The Hindu Group", "lean": "left", "language": "en", "url": "https://www.thehindu.com/brandhub/pr-release/fractal-wins-us-17m-multi-year-ai-deal-with-a-fortune-500-u-s-healthcare-organization/article71359919.ece", "headline": "Fractal Wins US$17M+ Multi-Year AI Deal with a Fortune 500® U.S. Healthcare Organization"}, {"source": "The Hindu BusinessLine", "owner": "The Hindu Group", "lean": "center", "language": "en", "url": "https://www.thehindubusinessline.com/brandhub/pr-release/fractal-wins-us-17m-multi-year-ai-deal-with-a-fortune-500-u-s-healthcare-organization/article71359921.ece", "headline": "Fractal Wins US$17M+ Multi-Year AI Deal with a Fortune 500® U.S. Healthcare Organization"}], "coverage": {"left": {"count": 1, "sources": ["The Hindu"], "owners": ["The Hindu Group"]}, "center": {"count": 1, "sources": ["The Hindu BusinessLine"], "owners": ["The Hindu Group"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://th-i.thgim.com/public/incoming/5vknad/article71359918.ece/alternates/LANDSCAPE_1200/Fractal_Logo.jpg', FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.257418'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15920, 'India Sets Minimum Import Price for Clear Float Glass', 'भारत ने क्लियर फ्लोट ग्लास पर न्यूनतम आयात मूल्य तय किया', 'India has imposed a minimum import price on clear float glass, a move aimed at curbing cheaper imports. The Directorate General of Foreign Trade reclassified the import policy for clear float glass, specifically items between 4 mm and 12 mm thickness, from "Free" to "Restricted." This decision is expected to benefit domestic manufacturers like Saint-Gobain and Asahi India.', 'भारत ने क्लियर फ्लोट ग्लास पर न्यूनतम आयात मूल्य लागू किया है, जिसका उद्देश्य सस्ते आयात को रोकना है। विदेश व्यापार महानिदेशालय ने क्लियर फ्लोट ग्लास (4 मिमी से 12 मिमी मोटाई) के लिए आयात नीति को "मुक्त" से "प्रतिबंधित" में बदल दिया है। इस निर्णय से सेंट-गोबेन और असाही इंडिया जैसे घरेलू निर्माताओं को लाभ होने की उम्मीद है।', '["India has imposed a minimum import price on clear float glass.", "The measure is intended to curb cheaper imports.", "The Directorate General of Foreign Trade changed the import status from \"Free\" to \"Restricted.\"", "The policy applies to clear float glass with thicknesses ranging from 4 mm to 12 mm.", "Manufacturers like Saint-Gobain and Asahi India are expected to benefit from this policy change."]'::jsonb, '["भारत ने क्लियर फ्लोट ग्लास पर न्यूनतम आयात मूल्य लागू किया है।", "इस उपाय का उद्देश्य सस्ते आयात को रोकना है।", "विदेश व्यापार महानिदेशालय ने \"मुक्त\" से \"प्रतिबंधित\" में आयात की स्थिति बदल दी है।", "यह नीति 4 मिमी से 12 मिमी मोटाई वाले क्लियर फ्लोट ग्लास पर लागू होती है।", "सेंट-गोबेन और असाही इंडिया जैसे निर्माताओं को इस नीतिगत बदलाव से लाभ होने की उम्मीद है।"]'::jsonb, 'Economy', 'India', 0, 2, 0, 0, 0, 2, 'center', 100, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["The Economic Times", "The Hindu BusinessLine"], "owners": ["The Hindu Group", "Times Group"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"center": ["Reported the government''s imposition of a minimum import price on clear float glass.", "Noted the policy change from \"Free\" to \"Restricted\" for imports.", "Mentioned the specific thickness range (4 mm to 12 mm) affected by the policy.", "Highlighted that domestic companies like Saint-Gobain and Asahi India are expected to benefit."]}'::jsonb, '{"center": ["क्लियर फ्लोट ग्लास पर न्यूनतम आयात मूल्य लागू करने के सरकारी फैसले की सूचना दी।", "आयात के लिए \"मुक्त\" से \"प्रतिबंधित\" में नीतिगत बदलाव का उल्लेख किया।", "नीति से प्रभावित विशिष्ट मोटाई सीमा (4 मिमी से 12 मिमी) का उल्लेख किया।", "इस बात पर प्रकाश डाला कि सेंट-गोबेन और असाही इंडिया जैसी घरेलू कंपनियों को लाभ होने की उम्मीद है।"]}'::jsonb, '[{"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "India imposes minimum import price on clear float glass to curb cheaper imports"}, {"source": "The Hindu BusinessLine", "owner": "The Hindu Group", "lean": "center", "language": "en", "url": "https://www.thehindubusinessline.com/news/india-imposes-minimum-import-price-on-clear-float-glass-benefiting-saint-gobain-asahi-india/article71359761.ece", "headline": "India imposes minimum import price on clear float glass, benefiting Saint-Gobain, Asahi India"}]'::jsonb, '{"title": "India Sets Minimum Import Price for Clear Float Glass", "summary": "India has imposed a minimum import price on clear float glass, a move aimed at curbing cheaper imports. The Directorate General of Foreign Trade reclassified the import policy for clear float glass, specifically items between 4 mm and 12 mm thickness, from \"Free\" to \"Restricted.\" This decision is expected to benefit domestic manufacturers like Saint-Gobain and Asahi India.", "summary_points": ["India has imposed a minimum import price on clear float glass.", "The measure is intended to curb cheaper imports.", "The Directorate General of Foreign Trade changed the import status from \"Free\" to \"Restricted.\"", "The policy applies to clear float glass with thicknesses ranging from 4 mm to 12 mm.", "Manufacturers like Saint-Gobain and Asahi India are expected to benefit from this policy change."], "title_hi": "भारत ने क्लियर फ्लोट ग्लास पर न्यूनतम आयात मूल्य तय किया", "summary_hi": "भारत ने क्लियर फ्लोट ग्लास पर न्यूनतम आयात मूल्य लागू किया है, जिसका उद्देश्य सस्ते आयात को रोकना है। विदेश व्यापार महानिदेशालय ने क्लियर फ्लोट ग्लास (4 मिमी से 12 मिमी मोटाई) के लिए आयात नीति को \"मुक्त\" से \"प्रतिबंधित\" में बदल दिया है। इस निर्णय से सेंट-गोबेन और असाही इंडिया जैसे घरेलू निर्माताओं को लाभ होने की उम्मीद है।", "summary_points_hi": ["भारत ने क्लियर फ्लोट ग्लास पर न्यूनतम आयात मूल्य लागू किया है।", "इस उपाय का उद्देश्य सस्ते आयात को रोकना है।", "विदेश व्यापार महानिदेशालय ने \"मुक्त\" से \"प्रतिबंधित\" में आयात की स्थिति बदल दी है।", "यह नीति 4 मिमी से 12 मिमी मोटाई वाले क्लियर फ्लोट ग्लास पर लागू होती है।", "सेंट-गोबेन और असाही इंडिया जैसे निर्माताओं को इस नीतिगत बदलाव से लाभ होने की उम्मीद है।"], "framing": {"center": ["Reported the government''s imposition of a minimum import price on clear float glass.", "Noted the policy change from \"Free\" to \"Restricted\" for imports.", "Mentioned the specific thickness range (4 mm to 12 mm) affected by the policy.", "Highlighted that domestic companies like Saint-Gobain and Asahi India are expected to benefit."]}, "framing_hi": {"center": ["क्लियर फ्लोट ग्लास पर न्यूनतम आयात मूल्य लागू करने के सरकारी फैसले की सूचना दी।", "आयात के लिए \"मुक्त\" से \"प्रतिबंधित\" में नीतिगत बदलाव का उल्लेख किया।", "नीति से प्रभावित विशिष्ट मोटाई सीमा (4 मिमी से 12 मिमी) का उल्लेख किया।", "इस बात पर प्रकाश डाला कि सेंट-गोबेन और असाही इंडिया जैसी घरेलू कंपनियों को लाभ होने की उम्मीद है।"]}, "topic": "Economy", "region": "India", "published_at": null, "image_url": "https://bl-i.thgim.com/public/incoming/mp189o/article71359876.ece/alternates/LANDSCAPE_1200/145095.II2", "sources": [{"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "India imposes minimum import price on clear float glass to curb cheaper imports"}, {"source": "The Hindu BusinessLine", "owner": "The Hindu Group", "lean": "center", "language": "en", "url": "https://www.thehindubusinessline.com/news/india-imposes-minimum-import-price-on-clear-float-glass-benefiting-saint-gobain-asahi-india/article71359761.ece", "headline": "India imposes minimum import price on clear float glass, benefiting Saint-Gobain, Asahi India"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["The Economic Times", "The Hindu BusinessLine"], "owners": ["The Hindu Group", "Times Group"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://bl-i.thgim.com/public/incoming/mp189o/article71359876.ece/alternates/LANDSCAPE_1200/145095.II2', FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.236761'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15919, 'Tamil Nadu Speaker Expunges Law Minister''s Remarks on Karunanidhi', 'तमिलनाडु विधानसभा अध्यक्ष ने करुणानिधि पर कानून मंत्री की टिप्पणियां हटाईं', 'Tamil Nadu Assembly Speaker M. Appavu expunged remarks made by Law Minister C.V.e. Nirmalkumar against former Chief Minister M. Karunanidhi. The Speaker also stated that only the member who gave notice would be allowed to speak during a special calling-attention motion under Rule 55 of the Assembly Rules. This action followed remarks made by the Law Minister concerning Karunanidhi. The Speaker emphasized adherence to the assembly''s rules.', 'तमिलनाडु विधानसभा अध्यक्ष एम. अप्पावु ने कानून मंत्री सी.वी.ई. निर्मलकुमार द्वारा पूर्व मुख्यमंत्री एम. करुणानिधि के खिलाफ की गई टिप्पणियों को कार्यवाही से हटवा दिया। अध्यक्ष ने यह भी स्पष्ट किया कि नियम 55 के तहत विशेष ध्यानाकर्षण प्रस्ताव के दौरान केवल नोटिस देने वाले सदस्य को ही बोलने की अनुमति दी जाएगी। यह कार्रवाई कानून मंत्री द्वारा करुणानिधि के संबंध में की गई टिप्पणियों के बाद हुई। अध्यक्ष ने सदन के नियमों का पालन करने पर जोर दिया।', '["Tamil Nadu Assembly Speaker M. Appavu expunged remarks made by Law Minister C.V.e. Nirmalkumar.", "The expunged remarks were against former Chief Minister M. Karunanidhi.", "The Speaker also clarified rules regarding special calling-attention motions.", "Only the member who gave notice will be permitted to speak during such motions.", "The Speaker stressed the importance of following Assembly Rule 55."]'::jsonb, '["तमिलनाडु विधानसभा अध्यक्ष एम. अप्पावु ने कानून मंत्री सी.वी.ई. निर्मलकुमार द्वारा की गई टिप्पणियों को कार्यवाही से हटवा दिया।", "हटाई गई टिप्पणियां पूर्व मुख्यमंत्री एम. करुणानिधि के खिलाफ थीं।", "अध्यक्ष ने विशेष ध्यानाकर्षण प्रस्तावों के संबंध में नियमों को भी स्पष्ट किया।", "ऐसे प्रस्तावों के दौरान केवल नोटिस देने वाले सदस्य को ही बोलने की अनुमति होगी।", "अध्यक्ष ने विधानसभा नियम 55 का पालन करने के महत्व पर जोर दिया।"]'::jsonb, 'Politics', 'India', 1, 1, 0, 0, 0, 2, 'left', 50, NULL, NULL, '{"left": {"count": 1, "sources": ["The Hindu"], "owners": ["The Hindu Group"]}, "center": {"count": 1, "sources": ["Outlook India"], "owners": ["Outlook India"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "The Hindu", "owner": "The Hindu Group", "lean": "left", "language": "en", "url": "https://www.thehindu.com/news/national/tamil-nadu/tamil-nadu-assembly-speaker-expunges-remarks-against-karunanidhi-by-minister-nirmalkumar/article71359489.ece", "headline": "Tamil Nadu Assembly Speaker expunges remarks against Karunanidhi by Law Minister Nirmalkumar"}, {"source": "Outlook India", "owner": "Outlook India", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Tamil Nadu Assembly Speaker Expunges Karunanidhi Remarks, Stresses House Rules"}]'::jsonb, '{"title": "Tamil Nadu Speaker Expunges Law Minister''s Remarks on Karunanidhi", "summary": "Tamil Nadu Assembly Speaker M. Appavu expunged remarks made by Law Minister C.V.e. Nirmalkumar against former Chief Minister M. Karunanidhi. The Speaker also stated that only the member who gave notice would be allowed to speak during a special calling-attention motion under Rule 55 of the Assembly Rules. This action followed remarks made by the Law Minister concerning Karunanidhi. The Speaker emphasized adherence to the assembly''s rules.", "summary_points": ["Tamil Nadu Assembly Speaker M. Appavu expunged remarks made by Law Minister C.V.e. Nirmalkumar.", "The expunged remarks were against former Chief Minister M. Karunanidhi.", "The Speaker also clarified rules regarding special calling-attention motions.", "Only the member who gave notice will be permitted to speak during such motions.", "The Speaker stressed the importance of following Assembly Rule 55."], "title_hi": "तमिलनाडु विधानसभा अध्यक्ष ने करुणानिधि पर कानून मंत्री की टिप्पणियां हटाईं", "summary_hi": "तमिलनाडु विधानसभा अध्यक्ष एम. अप्पावु ने कानून मंत्री सी.वी.ई. निर्मलकुमार द्वारा पूर्व मुख्यमंत्री एम. करुणानिधि के खिलाफ की गई टिप्पणियों को कार्यवाही से हटवा दिया। अध्यक्ष ने यह भी स्पष्ट किया कि नियम 55 के तहत विशेष ध्यानाकर्षण प्रस्ताव के दौरान केवल नोटिस देने वाले सदस्य को ही बोलने की अनुमति दी जाएगी। यह कार्रवाई कानून मंत्री द्वारा करुणानिधि के संबंध में की गई टिप्पणियों के बाद हुई। अध्यक्ष ने सदन के नियमों का पालन करने पर जोर दिया।", "summary_points_hi": ["तमिलनाडु विधानसभा अध्यक्ष एम. अप्पावु ने कानून मंत्री सी.वी.ई. निर्मलकुमार द्वारा की गई टिप्पणियों को कार्यवाही से हटवा दिया।", "हटाई गई टिप्पणियां पूर्व मुख्यमंत्री एम. करुणानिधि के खिलाफ थीं।", "अध्यक्ष ने विशेष ध्यानाकर्षण प्रस्तावों के संबंध में नियमों को भी स्पष्ट किया।", "ऐसे प्रस्तावों के दौरान केवल नोटिस देने वाले सदस्य को ही बोलने की अनुमति होगी।", "अध्यक्ष ने विधानसभा नियम 55 का पालन करने के महत्व पर जोर दिया।"], "framing": {}, "framing_hi": {}, "topic": "Politics", "region": "India", "published_at": null, "image_url": "https://th-i.thgim.com/public/incoming/qyhiu7/article71359537.ece/alternates/LANDSCAPE_1200/2085_8_7_2026_13_55_3_3_DSC_3854.JPG", "sources": [{"source": "The Hindu", "owner": "The Hindu Group", "lean": "left", "language": "en", "url": "https://www.thehindu.com/news/national/tamil-nadu/tamil-nadu-assembly-speaker-expunges-remarks-against-karunanidhi-by-minister-nirmalkumar/article71359489.ece", "headline": "Tamil Nadu Assembly Speaker expunges remarks against Karunanidhi by Law Minister Nirmalkumar"}, {"source": "Outlook India", "owner": "Outlook India", "lean": "center", "language": "en", "url": "h